//! Every Vim command, from Vim's own index (`:help index`), and how much of
//! it Flow Buddy teaches and coaches. Generated by `scripts/vim-index.py`.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use crate::curriculum::{items_of_command, rule_skills};

/// One command from Vim's index.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Entry {
    /// insert, normal, visual, cmdline, terminal or ex.
    pub mode: &'static str,
    /// Where in the index: text-objects, windows, g, z, brackets…
    pub section: &'static str,
    /// Its help tag: `v_iw`, `CTRL-W_j`, `:sort`.
    pub tag: &'static str,
    /// As the index writes it: `["x]d{motion}`, `:sor[t]`.
    pub keys: &'static str,
    pub what: &'static str,
}

static DATA: &str = include_str!("../data/vim-index.tsv");

/// Vim's index, parsed once.
pub fn entries() -> &'static [Entry] {
    static ENTRIES: OnceLock<Vec<Entry>> = OnceLock::new();
    ENTRIES.get_or_init(|| {
        DATA.lines()
            .filter(|l| !l.starts_with('#'))
            .skip(1)
            .filter_map(|l| {
                let mut f = l.splitn(5, '\t');
                let (mode, section, tag, keys, what) =
                    (f.next()?, f.next()?, f.next()?, f.next()?, f.next()?);
                // Normal-mode rows start with a note: 1 moves the cursor,
                // 2 can be undone.
                let what = what.trim_start_matches(['1', '2']).trim_start();
                Some(Entry {
                    mode,
                    section,
                    tag,
                    keys,
                    what,
                })
            })
            .collect()
    })
}

/// The command as a tip would write it, to recognise: `["x]d{motion}` →
/// `dw`, `CTRL-W j` → `Ctrl-w j`, `:sor[t]` → `:sort`, the text object
/// `iw` → `diw`.
fn as_command(e: &Entry) -> Option<String> {
    let mut k = e.keys.replace("[\"x]", "").replace("[count]", "");
    if e.mode == "ex" {
        let name = k.trim_start_matches(':').replace(['[', ']'], "");
        let name = name.split_whitespace().next().unwrap_or("").to_string();
        return (!name.is_empty() && !name.contains('{')).then(|| format!(":{name}"));
    }
    for (from, to) in [
        ("{motion}", "w"),
        ("{char}", "x"),
        ("{char1}", "x"),
        ("{char2}", "y"),
        ("{a-z}", "a"),
        ("{a-zA-Z0-9.%#:-\"}", "a"),
        ("{a-zA-Z}", "a"),
        ("{a-z0-9}", "a"),
        ("{count}", ""),
        ("{height}", ""),
        ("{filter}", ""),
        ("{mode}", ""),
        ("{regname}", "a"),
        ("{register}", "a"),
    ] {
        k = k.replace(from, to);
    }
    // A placeholder left over ({pattern}) or a special key (<BS>, <Tab>):
    // nothing to type for it.
    if placeholder(&k, '{', '}') || placeholder(&k, '<', '>') {
        return None;
    }
    // A count: N%, N<<.
    if k.len() > 1 {
        k = k.trim_start_matches('N').to_string();
    }
    // CTRL-X → Ctrl-x; keys are separated by spaces in the index.
    let keys: String = k
        .split(' ')
        .filter(|p| !p.is_empty())
        .map(|p| match p.strip_prefix("CTRL-") {
            Some(c) if c.chars().count() == 1 => format!("Ctrl-{}", c.to_lowercase()),
            Some(_) => String::new(),
            None => p.to_string(),
        })
        .collect::<Vec<_>>()
        .join("");
    if keys.is_empty() {
        return None;
    }
    Some(match (e.mode, e.section) {
        ("normal", "text-objects") => format!("d{keys}"),
        ("visual", _) => format!("v{keys}"),
        _ => keys,
    })
}

/// Whether `k` holds `open`, a word, then `close`: `{pattern}`, `<BS>`.
fn placeholder(k: &str, open: char, close: char) -> bool {
    k.match_indices(open).any(|(i, _)| {
        let rest = &k[i + 1..];
        rest.find(close).is_some_and(|end| {
            end > 1
                && rest[..end]
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || c == '-')
        })
    })
}

/// What you start with: Flow Buddy coaches you on from these rather than
/// teaching them.
const STARTING: &[&str] = &["h", "j", "k", "l", "i", "a", "v", "x", ":", "q", "ZQ"];

/// What Flow Buddy does with one command.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Covered {
    /// A rule can spot when you'd want it, and the curriculum teaches it.
    Coached,
    /// The curriculum teaches it; no rule spots the need.
    Taught,
    /// Where everyone starts; rules coach you past it.
    Starting,
    /// Not yet.
    No,
}

pub fn covered(e: &Entry) -> Covered {
    if e.mode == "normal" && STARTING.contains(&e.keys) {
        return Covered::Starting;
    }
    let Some(cmd) = as_command(e) else {
        return Covered::No;
    };
    // Insert-mode keys mean something else in Normal mode: no guessing.
    if matches!(e.mode, "insert" | "cmdline" | "terminal") {
        return Covered::No;
    }
    let items = items_of_command(&cmd);
    if items.is_empty() {
        return Covered::No;
    }
    let coached = crate::rules::all().iter().any(|r| {
        rule_skills(r.id()).is_some_and(|skills| items.iter().any(|i| skills.contains(i)))
    });
    if coached {
        Covered::Coached
    } else {
        Covered::Taught
    }
}

/// Per mode: (commands, taught or coached, coached).
pub fn coverage() -> BTreeMap<&'static str, (usize, usize, usize)> {
    let mut out: BTreeMap<&'static str, (usize, usize, usize)> = BTreeMap::new();
    for e in entries() {
        let c = covered(e);
        let row = out.entry(e.mode).or_default();
        row.0 += 1;
        row.1 += usize::from(matches!(c, Covered::Coached | Covered::Taught));
        row.2 += usize::from(c == Covered::Coached);
    }
    out
}

/// Everyday commands not covered yet: Normal and Visual mode, short to
/// type, and not a no-op or obsolete.
pub fn gaps() -> Vec<&'static Entry> {
    entries()
        .iter()
        .filter(|e| matches!(e.mode, "normal" | "visual"))
        .filter(|e| e.keys.chars().count() <= 3 && !e.what.is_empty())
        // Count digits: taught as a count.
        .filter(|e| !(e.keys.len() == 1 && e.keys.as_bytes()[0].is_ascii_digit()))
        .filter(|e| {
            let w = e.what.to_lowercase();
            !(w.contains("not used")
                || w.contains("no-op")
                || w.starts_with("same as")
                || w.contains("reserved"))
        })
        .filter(|e| covered(e) == Covered::No)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reads_vims_index() {
        let all = entries();
        assert!(all.len() > 1200, "{}", all.len());
        let w = all.iter().find(|e| e.tag == "w").unwrap();
        assert_eq!((w.mode, w.what), ("normal", "cursor N words forward"));
    }

    #[test]
    fn commands_map_to_what_teaches_them() {
        let find = |tag: &str| entries().iter().find(|e| e.tag == tag).unwrap();
        assert_eq!(as_command(find("d")).as_deref(), Some("dw"));
        assert_eq!(as_command(find(":sort")).as_deref(), Some(":sort"));
        assert_eq!(covered(find("w")), Covered::Coached);
        assert_eq!(covered(find(":sort")), Covered::Taught);
        assert_eq!(covered(find("v_iw")), Covered::Coached, "diw");
        assert_eq!(covered(find("{")), Covered::Coached, "paragraph");
        assert_ne!(covered(find("N")), Covered::No, "search-back");
        assert_eq!(covered(find("j")), Covered::Starting);
        assert!(placeholder("d{motion}", '{', '}') && !placeholder("[{", '{', '}'));
        assert!(placeholder("<BS>", '<', '>') && !placeholder("a<", '<', '>'));
        let c = coverage();
        assert!(c["normal"].1 > 50, "{c:?}");
    }
}
